public class ScheduleAuditProbe implements Database.Batchable<SObject> {
 public Database.QueryLocator start(Database.BatchableContext c){return Database.getQueryLocator('SELECT Id FROM Account WHERE Name=\'audit-empty-owned\'');}
 public void execute(Database.BatchableContext c,List<SObject> rows){} public void finish(Database.BatchableContext c){}
 public static String enqueue(){return System.scheduleBatch(new ScheduleAuditProbe(),'owned-audit-delay',5,1);}
 public static Map<String,Object> snapshot(String key){
  List<CronTrigger> rows=[SELECT CreatedDate,NextFireTime,StartTime,CronExpression FROM CronTrigger WHERE Id=:key];Map<String,Object> r=new Map<String,Object>{'rows'=>rows.size()};
  if(rows.isEmpty())return r;CronTrigger c=rows[0];r.put('createdPresent',c.CreatedDate!=null);r.put('createdMilliseconds',c.CreatedDate==null?null:c.CreatedDate.formatGmt('SSS'));r.put('createdNearClock',c.CreatedDate!=null&&Math.abs(System.now().getTime()-c.CreatedDate.getTime())<60000);
  r.put('nextPresent',c.NextFireTime!=null);r.put('nextMilliseconds',c.NextFireTime==null?null:c.NextFireTime.formatGmt('SSS'));r.put('minuteMatches',c.CreatedDate!=null&&c.NextFireTime!=null&&c.CreatedDate.addMinutes(5).minute()==c.NextFireTime.minute());
  r.put('simpleTrigger',c.CronExpression=='SimpleTrigger');return r;
 }
 public static Map<String,Object> anonymous(){String key=enqueue();Map<String,Object> r=snapshot(key);System.abortJob(key);return r;}
}

